settings.custom_liquid:
{% assign deadline = '2026-11-30T23:59:59-05:00' %}
{%- liquid
  assign now_s = 'now' | date: '%s' | plus: 0

  comment
    November 2026 promo ladder. Each card is gated on the clock, server-side, so the
    homepage changes offers on its own: a tier disappears the moment it ends (a card you
    can no longer use reads as a loss, not an incentive), and the Black Friday card is
    hidden until it starts — the owner wanted it unannounced. Times are Toronto, EST.
    The discounts themselves are automatic discounts in admin; this only describes them.
  endcomment
  assign sale20_end = '2026-11-05T23:59:59-05:00' | date: '%s' | plus: 0
  assign sale15_end = '2026-11-15T23:59:59-05:00' | date: '%s' | plus: 0
  assign sale10_end = '2026-11-26T19:59:59-05:00' | date: '%s' | plus: 0
  assign bf_start = '2026-11-26T20:00:00-05:00' | date: '%s' | plus: 0
  assign bf_end = '2026-11-30T23:59:59-05:00' | date: '%s' | plus: 0
  assign tier_count = 0
  if now_s <= sale20_end
    assign tier_count = tier_count | plus: 1
  endif
  if now_s <= sale15_end
    assign tier_count = tier_count | plus: 1
  endif
  if now_s <= sale10_end
    assign tier_count = tier_count | plus: 1
  endif
  if now_s >= bf_start and now_s <= bf_end
    assign tier_count = tier_count | plus: 1
  endif
-%}

<style>
  .aga-batch {
    max-width: 760px; margin: 0 auto; text-align: center; color: #2F2A22;
    padding: clamp(56px, 8vw, 92px) 20px;
  }
  .aga-batch__added {
    margin: 0 0 clamp(16px, 2.6vw, 22px); color: #9F582E;
    font-family: var(--font-body--family, "Work Sans", sans-serif);
    font-size: 11px; font-weight: 600; letter-spacing: .18em; text-transform: uppercase;
  }
  .aga-batch__title {
    margin: 0; color: #2F2A22;
    font-family: var(--font-accent--family, Lora, serif);
    font-weight: 400; font-size: clamp(22px, 4.4vw, 30px); line-height: 1.25;
  }
  .aga-batch__timer {
    display: flex; justify-content: center; max-width: 520px;
    margin: clamp(26px, 4vw, 38px) auto 0;
  }
  .aga-batch__unit { position: relative; flex: 1 1 0; padding: 0 clamp(6px, 2vw, 16px); }
  .aga-batch__unit + .aga-batch__unit::before {
    content: ""; position: absolute; left: 0; top: 4%; bottom: 20%;
    width: 1px; background: rgb(47 42 34 / .14);
  }
  .aga-batch__num {
    display: block; color: #2F2A22;
    font-family: var(--font-accent--family, Lora, serif);
    font-weight: 400; font-size: clamp(30px, 8vw, 48px); line-height: 1;
    font-variant-numeric: tabular-nums; font-feature-settings: "tnum" 1;
  }
  .aga-batch__lbl {
    display: block; margin-top: clamp(8px, 1.6vw, 12px); color: #56503F;
    font-family: var(--font-body--family, "Work Sans", sans-serif);
    font-size: 10px; font-weight: 500; letter-spacing: .18em; text-transform: uppercase;
  }
  .aga-batch__sub {
    margin: clamp(26px, 4vw, 36px) auto 0; max-width: 44ch; color: #56503F;
    font-family: var(--font-body--family, "Work Sans", sans-serif);
    font-size: 15px; font-weight: 400; line-height: 1.65;
  }
  .aga-batch__cta {
    display: inline-block; margin-top: clamp(24px, 3.5vw, 32px);
    padding: 15px 34px; border-radius: 2px; background: #5C6B4C; color: #FBF8F2;
    font-family: var(--font-body--family, "Work Sans", sans-serif);
    font-size: 12px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase;
    text-decoration: none; transition: background-color .2s ease;
  }
  .aga-batch__cta:hover, .aga-batch__cta:focus { background: #4A573D; color: #FBF8F2; }
  .aga-batch__tiers {
    display: grid; grid-template-columns: repeat(var(--tiers, 4), minmax(0, 1fr)); gap: 12px;
    margin: clamp(28px, 4vw, 40px) auto 0; padding: 0; list-style: none;
    max-width: max(300px, calc(var(--tiers, 4) * 190px));
  }
  .aga-batch__tier {
    position: relative; padding: 16px 10px 14px;
    border: 1px solid rgb(47 42 34 / .14); border-radius: 2px;
    background: rgb(251 248 242 / .7);
  }
  .aga-batch__tier.is-now { background: #5C6B4C; border-color: #5C6B4C; color: #FBF8F2; }
  .aga-batch__pill {
    position: absolute; top: -9px; left: 50%; transform: translateX(-50%);
    padding: 3px 10px; border-radius: 999px; background: #9F582E; color: #FBF8F2;
    font-family: var(--font-body--family, "Work Sans", sans-serif);
    font-size: 9px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase;
    white-space: nowrap;
  }
  .aga-batch__when {
    display: block; color: #56503F;
    font-family: var(--font-body--family, "Work Sans", sans-serif);
    font-size: 10px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase;
  }
  .aga-batch__off {
    display: block; margin-top: 6px;
    font-family: var(--font-accent--family, Lora, serif);
    font-weight: 400; font-size: clamp(20px, 3.2vw, 27px); line-height: 1.1;
  }
  .aga-batch__min {
    display: block; margin-top: 6px; color: #56503F;
    font-family: var(--font-body--family, "Work Sans", sans-serif);
    font-size: 9px; font-weight: 600; letter-spacing: .12em; text-transform: uppercase;
  }
  .aga-batch__tier.is-now .aga-batch__when,
  .aga-batch__tier.is-now .aga-batch__min { color: #FBF8F2; }
  @media (max-width: 560px) {
    .aga-batch__tiers { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; max-width: none; }
    .aga-batch__tier:last-child:nth-child(odd) { grid-column: span 2; }
  }
  @media (max-width: 420px) {
    .aga-batch__lbl { font-size: 9px; letter-spacing: .12em; }
  }
</style>

<section class="aga-batch" data-deadline="{{ deadline }}">
  <p class="aga-batch__added">New batch now open</p>

  <h2 class="aga-batch__title">This batch closes in</h2>

  <div class="aga-batch__timer">
    <div class="aga-batch__unit"><span class="aga-batch__num" data-u="d">--</span><span class="aga-batch__lbl">Days</span></div>
    <div class="aga-batch__unit"><span class="aga-batch__num" data-u="h">--</span><span class="aga-batch__lbl">Hours</span></div>
    <div class="aga-batch__unit"><span class="aga-batch__num" data-u="m">--</span><span class="aga-batch__lbl">Min</span></div>
    <div class="aga-batch__unit"><span class="aga-batch__num" data-u="s">--</span><span class="aga-batch__lbl">Sec</span></div>
  </div>

  {% if tier_count > 0 %}
  <ol class="aga-batch__tiers" style="--tiers: {{ tier_count }};">
    {% if now_s <= sale20_end %}
    <li class="aga-batch__tier is-now">
      <span class="aga-batch__pill">Now</span>
      <span class="aga-batch__when">Nov 1&ndash;5</span>
      <span class="aga-batch__off">20% off</span>
      <span class="aga-batch__min">Orders $100+</span>
    </li>
    {% endif %}
    {% if now_s <= sale15_end %}
    <li class="aga-batch__tier{% if now_s > sale20_end %} is-now{% endif %}">
      {% if now_s > sale20_end %}<span class="aga-batch__pill">Now</span>{% endif %}
      <span class="aga-batch__when">Nov 6&ndash;15</span>
      <span class="aga-batch__off">15% off</span>
      <span class="aga-batch__min">Orders $100+</span>
    </li>
    {% endif %}
    {% if now_s <= sale10_end %}
    <li class="aga-batch__tier{% if now_s > sale15_end %} is-now{% endif %}">
      {% if now_s > sale15_end %}<span class="aga-batch__pill">Now</span>{% endif %}
      <span class="aga-batch__when">Nov 16&ndash;26</span>
      <span class="aga-batch__off">10% off</span>
      <span class="aga-batch__min">Orders $100+</span>
    </li>
    {% endif %}
    {% if now_s >= bf_start and now_s <= bf_end %}
    <li class="aga-batch__tier is-now">
      <span class="aga-batch__pill">Now</span>
      <span class="aga-batch__when">Nov 26&ndash;30 &middot; Black Friday</span>
      <span class="aga-batch__off">Up to 40% off</span>
      <span class="aga-batch__min">Ready to ship 40% &middot; Acclimated 30% &middot; Pre-orders 10&ndash;20%</span>
    </li>
    {% endif %}
  </ol>
  {% endif %}

  <p class="aga-batch__sub">Every batch is repriced to supply and demand &mdash; up or down. Yours is locked the moment you order.</p>
  <a class="aga-batch__cta" href="/collections/pre-order">Lock in this batch&rsquo;s price</a>
</section>

<script>
(function () {
  function init(box) {
    if (box.getAttribute('data-ready')) return;
    box.setAttribute('data-ready', '1');
    var end = new Date(box.getAttribute('data-deadline')).getTime();
    var q = function (sel) { return box.querySelector(sel); };
    var pad = function (n) { return (n < 10 ? '0' : '') + n; };
    function tick() {
      var left = end - Date.now();
      if (isNaN(end) || left <= 0) {
        clearInterval(timer);
        q('.aga-batch__timer').style.display = 'none';
        q('.aga-batch__added').style.display = 'none';
        if (q('.aga-batch__tiers')) q('.aga-batch__tiers').style.display = 'none';
        q('.aga-batch__title').textContent = 'This batch has closed';
        q('.aga-batch__sub').textContent = 'The next batch opens at new pricing. Ready-to-ship plants are available now.';
        q('.aga-batch__cta').textContent = 'Shop ready to ship';
        q('.aga-batch__cta').href = '/collections/ready-to-ship-tissue-culture';
        return;
      }
      var s = Math.floor(left / 1000);
      q('[data-u="d"]').textContent = pad(Math.floor(s / 86400));
      q('[data-u="h"]').textContent = pad(Math.floor(s % 86400 / 3600));
      q('[data-u="m"]').textContent = pad(Math.floor(s % 3600 / 60));
      q('[data-u="s"]').textContent = pad(s % 60);
    }
    var timer = setInterval(tick, 1000);
    tick();
  }
  function run() {
    var all = document.querySelectorAll('.aga-batch');
    for (var i = 0; i < all.length; i++) init(all[i]);
  }
  run();
  document.addEventListener('DOMContentLoaded', run);
  document.addEventListener('shopify:section:load', run);
})();
</script>
